-- IAM bounded context: tenants, users, roles, invitations, OTPs, sessions, refresh tokens.
-- Conventions: uuid primary keys generated by the application, timestamptz everywhere,
-- status columns constrained with CHECK, every tenant-owned row carries tenant_id.

CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE tenants (
    id          uuid PRIMARY KEY,
    slug        text NOT NULL UNIQUE,
    name        text NOT NULL,
    status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id                  uuid PRIMARY KEY,
    tenant_id           uuid NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    email               citext NOT NULL,
    name                text NOT NULL,
    status              text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'suspended')),
    scopes              text[] NOT NULL DEFAULT '{}',
    -- Bumped on suspension; tokens carrying an older version are rejected.
    credential_version  bigint NOT NULL DEFAULT 1,
    email_verified      boolean NOT NULL DEFAULT false,
    otp_enabled         boolean NOT NULL DEFAULT true,
    last_login_at       timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, email)
);

CREATE INDEX users_email_idx ON users (email);

CREATE TABLE roles (
    id          uuid PRIMARY KEY,
    tenant_id   uuid NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    name        text NOT NULL,
    description text NOT NULL DEFAULT '',
    scopes      text[] NOT NULL DEFAULT '{}',
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, name)
);

CREATE TABLE user_roles (
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role_id     uuid NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
    assigned_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_id)
);

CREATE INDEX user_roles_role_idx ON user_roles (role_id);

CREATE TABLE invitations (
    id                uuid PRIMARY KEY,
    tenant_id         uuid NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    email             citext NOT NULL,
    -- SHA-256 of the raw token. The raw token is only handed to the notifier.
    token_hash        bytea NOT NULL UNIQUE,
    scopes            text[] NOT NULL DEFAULT '{}',
    role_id           uuid REFERENCES roles (id) ON DELETE SET NULL,
    invited_by        uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    status            text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'revoked', 'expired')),
    expires_at        timestamptz NOT NULL,
    accepted_at       timestamptz,
    accepted_user_id  uuid REFERENCES users (id) ON DELETE SET NULL,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now()
);

-- At most one pending invitation per tenant and email.
CREATE UNIQUE INDEX invitations_pending_unique ON invitations (tenant_id, email) WHERE status = 'pending';
CREATE INDEX invitations_tenant_idx ON invitations (tenant_id, created_at DESC);

CREATE TABLE otps (
    id            uuid PRIMARY KEY,
    -- Email the code was sent to. OTPs prove mailbox ownership, not tenant membership.
    contact       citext NOT NULL,
    -- SHA-256 of the numeric code; compared in constant time by the service.
    code_hash     bytea NOT NULL,
    purpose       text NOT NULL CHECK (purpose IN ('signup', 'login')),
    expires_at    timestamptz NOT NULL,
    verified_at   timestamptz,
    attempts      integer NOT NULL DEFAULT 0,
    max_attempts  integer NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CHECK (attempts >= 0 AND attempts <= max_attempts)
);

CREATE INDEX otps_contact_purpose_idx ON otps (contact, purpose, created_at DESC);
CREATE INDEX otps_expires_idx ON otps (expires_at);

CREATE TABLE sessions (
    id                uuid PRIMARY KEY,
    user_id           uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    tenant_id         uuid NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    ip_address        text NOT NULL DEFAULT '',
    user_agent        text NOT NULL DEFAULT '',
    expires_at        timestamptz NOT NULL,
    revoked_at        timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now(),
    last_activity_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX sessions_user_idx ON sessions (user_id, created_at);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

CREATE TABLE refresh_tokens (
    id                  uuid PRIMARY KEY,
    -- SHA-256 of the opaque token handed to the client.
    token_hash          bytea NOT NULL UNIQUE,
    user_id             uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    tenant_id           uuid NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    session_id          uuid NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
    credential_version  bigint NOT NULL,
    expires_at          timestamptz NOT NULL,
    revoked_at          timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX refresh_tokens_session_idx ON refresh_tokens (session_id);
CREATE INDEX refresh_tokens_user_idx ON refresh_tokens (user_id);
